import json
from scipy.special import erf
gelu=lambda x: 0.5*x*(1+erf(x/np.sqrt(2)))
d=np.load('base_feats.npz'); y=d['y']; n=len(y)
def ln(x): x=x-x.mean(1,keepdims=True); return x/np.sqrt((x**2).mean(1,keepdims=True)+1e-12)
def stdz(X): return (X-X.mean(0))/(X.std(0)+1e-6)
def cvk(Z, lam=0.01, beta=1.0, seeds=3):
    K=gelu(beta*Z@Z.T/Z.shape[1]); accs=[]
    for seed in range(seeds):
        f=np.random.default_rng(seed).permutation(n)%5; P=np.zeros((n,8))
        for j in range(5):
            tr=f!=j; te=~tr; T=np.eye(8)[y[tr]]; b=T.mean(0)
            A=np.linalg.solve(K[np.ix_(tr,tr)]+lam*np.eye(tr.sum()),T-b); P[te]=K[np.ix_(te,tr)]@A+b
        accs.append((P.argmax(1)==y).mean())
    return np.mean(accs)
Z0=stdz(ln(d['cls11']+2*d['mean11']))
X=np.hstack([d['cls11'],d['mean11']]); Xc=X-X.mean(0); Y=d['mean0']-d['mean0'].mean(0)
for lam in [1,10,100]:
    # out-of-fold R2 of regression (unsupervised)
    f=np.arange(n)%5; Yh=np.zeros_like(Y)
    for j in range(5):
        tr=f!=j; B=np.linalg.solve(Xc[tr].T@Xc[tr]+lam*np.eye(X.shape[1]),Xc[tr].T@Y[tr]); Yh[~tr]=Xc[~tr]@B
    B=np.linalg.solve(Xc.T@Xc+lam*np.eye(X.shape[1]),Xc.T@Y); Yfit=Xc@B
    print(lam, 'oofR2', 1-((Y-Yh)**2).sum()/(Y**2).sum(), 'cv kernel w/ oof mean0hat', round(cvk(np.hstack([Z0,stdz(Yh)])),4), 'w/ fit', round(cvk(np.hstack([Z0,stdz(Yfit)])),4))
